import org.eclipse.jetty.util.VirtualThreads
import org.eclipse.jetty.util.thread.QueuedThreadPool
import org.eclipse.jetty.util.thread.ThreadPool
import java.net.URI
import java.net.http.HttpClient
import java.net.http.HttpRequest
import java.net.http.HttpResponse

/** What does a default Jetty 12 server start, and which thread runs a blocking vs a non-blocking handler? */
private val client = HttpClient.newBuilder().proxy(HttpClient.Builder.NO_PROXY).build()

private fun where() = Thread.currentThread().let { "${it.name} virtual=${it.isVirtual}" }

private class KtBlocking : Handler.Abstract() {                       // declares BLOCKING
    override fun handle(request: Request, response: Response, callback: Callback): Boolean {
        Content.Sink.write(response, true, where(), callback)
        return true
    }
}

private class KtNonBlocking : Handler.Abstract.NonBlocking() {        // declares NON_BLOCKING
    override fun handle(request: Request, response: Response, callback: Callback): Boolean {
        Content.Sink.write(response, true, where(), callback)
        return true
    }
}

private fun startServer(pool: ThreadPool, handler: Handler): Server = Server(pool).apply {
    addConnector(ServerConnector(this).apply { host = "127.0.0.1"; port = 0 })
    this.handler = handler
    start()
}

private fun get(server: Server): String {
    val port = (server.connectors[0] as ServerConnector).localPort
    return client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:$port/")).build(), HttpResponse.BodyHandlers.ofString()).body()
}

fun main() {
    val defaults = QueuedThreadPool()
    var server = startServer(defaults, KtBlocking())
    val c = server.connectors[0] as ServerConnector
    println("cpus=${Runtime.getRuntime().availableProcessors()} acceptors=${c.acceptors} selectors=${c.selectorManager.selectorCount}")
    println("QueuedThreadPool min=${defaults.minThreads} max=${defaults.maxThreads} started=${defaults.threads} leased=${defaults.leasedThreads}")
    println("[platform pool] BLOCKING handler     -> ${get(server)}")
    server.stop()
    server = startServer(QueuedThreadPool(), KtNonBlocking())
    println("[platform pool] NON_BLOCKING handler -> ${get(server)}")
    server.stop()

    for (blocking in listOf(true, false)) {
        val pool = QueuedThreadPool()
        pool.virtualThreadsExecutor = VirtualThreads.getNamedVirtualThreadsExecutor("jetty-vt-")
        server = startServer(pool, if (blocking) KtBlocking() else KtNonBlocking())
        println("[pool + virtual threads] ${if (blocking) "BLOCKING handler     -> " else "NON_BLOCKING handler -> "}${get(server)}")
        server.stop()
    }
}

sections.body:
Jetty 12 rewrote the API at its center. In Jetty 11 a handler had a blocking signature built on Servlet types. In Jetty 12 it is `boolean handle(Request request, Response response, Callback callback)`, and the migration guide spells out the new contract: return `true` to say you handled the request, and then complete the `Callback`, by succeeding or failing it, possibly long after `handle` has returned. Return `false` and Jetty moves on; with no other handler, the client gets a 404.

A blocking handler is the simple case: do the work, write the response with `Content.Sink.write(response, true, text, callback)`, which completes the callback once the bytes are written, and return `true`. A non-blocking handler reads the body without waiting for it:

```java
public class EchoHandler extends Handler.Abstract.NonBlocking {
    @Override
    public boolean handle(Request request, Response response, Callback callback) {
        Content.Source.asStringAsync(request, UTF_8).whenComplete((body, failure) -> {
            if (failure != null) {
                Response.writeError(request, response, callback, failure);
                return;
            }
            Content.Sink.write(response, true, "echo: " + body, callback);   // completes the callback
        });
        return true;   // "I took this request"; the response finishes later
    }
}
```

```kotlin
class EchoHandler : Handler.Abstract.NonBlocking() {
    override fun handle(request: Request, response: Response, callback: Callback): Boolean {
        Content.Source.asStringAsync(request, UTF_8).whenComplete { body, failure ->
            if (failure != null) {
                Response.writeError(request, response, callback, failure)
            } else {
                Content.Sink.write(response, true, "echo: $body", callback)  // completes the callback
            }
        }
        return true   // "I took this request"; the response finishes later
    }
}
```

The request body is a `Content.Source`: you read it in `Content.Chunk`s, which are slices of Jetty's network buffers, passed up without copying. The rule echoes Netty's reference counting from lesson 4: every chunk you `read()` must be released, except failure chunks, and a source must be read to the end or failed, or Jetty can leak its buffers. Helpers such as `asStringAsync` do the reading and releasing for you.

The superclass is a declaration. `Handler.Abstract` says "I may block" (`InvocationType.BLOCKING`). `Handler.Abstract.NonBlocking` says "I never block", and Jetty uses that promise to pick a thread, as the next section shows.

The Servlet API still exists, as a layer on top of this core. Jetty 12 ships it in separate environments named after Jakarta EE versions: `ee8`, `ee9`, `ee10`, and since 12.1 `ee11`, which brings Servlet 6.1. The docs list the core API's strengths as simple, minimal and asynchronous, with low overhead because you only configure what you use.

